{
  "schema_version": 1,
  "diagram_type": "architecture",
  "meta": {
    "title": "Order service",
    "output": "architecture.html",
    "input_contract": "phoenix-v1",
    "quality_profile": "showcase",
    "locale": "en"
  },
  "layout": {
    "mode": "grid",
    "cols": 3
  },
  "components": [
    {
      "id": "client",
      "type": "frontend",
      "label": "Customer portal",
      "row": 0,
      "col": 0
    },
    {
      "id": "service",
      "type": "backend",
      "label": "Order API",
      "row": 0,
      "col": 1
    },
    {
      "id": "database",
      "type": "database",
      "label": "Order store",
      "row": 0,
      "col": 2
    }
  ],
  "connections": [
    {
      "id": "request",
      "from": "client",
      "to": "service",
      "label": "Submit order"
    },
    {
      "id": "persist",
      "from": "service",
      "to": "database",
      "label": "Persist order"
    }
  ]
}
